<div class="page-heading"><div><div class="breadcrumb-line">Home <span>&rsaquo;</span> Stock / Parts <span>&rsaquo;</span> <b>Low Stock</b></div><h1>Low Stock</h1><p>Items that need replenishment are listed here.</p></div><div class="stock-heading-actions"><a href="index.php?page=admin&amp;section=stock-restock" class="btn btn-light">+ Restock Item</a><a href="index.php?page=admin&amp;section=stock-add" class="btn btn-danger">+ Add New Item</a></div></div>
<div class="admin-panel stock-list stock-low-list"><div class="panel-heading"><h2>Low Stock Items</h2><span class="text-muted"><?= count($rows) ?> items</span></div><div class="table-responsive"><table class="table admin-table stock-table"><thead><tr><th>Part No.</th><th>Part Name</th><th>Category</th><th>Current Qty</th><th>Reorder Level</th><th>Shortage</th><th>Status</th><th>Action</th></tr></thead><tbody><?php if(!$rows): ?><tr><td colspan="8" class="empty-table">No low stock items. All active items are above their minimum level.</td></tr><?php else: foreach($rows as $row): ?><tr><td><?= e($row['part_code']) ?></td><td><strong><?= e($row['part_name']) ?></strong></td><td><?= e($row['category']?:'-') ?></td><td><?= number_format((float)$row['stock_qty'],2) ?></td><td><?= number_format((float)$row['reorder_level'],2) ?></td><td><?= number_format(max(0,(float)$row['reorder_level']-(float)$row['stock_qty']),2) ?></td><td><span class="stock-status stock-status-<?= (float)$row['stock_qty']<=0?'out':'low' ?>"><?= (float)$row['stock_qty']<=0?'Out of Stock':'Low Stock' ?></span></td><td><div class="stock-low-actions"><a class="stock-view-button" href="index.php?page=admin&amp;section=stock-view&amp;id=<?= (int)$row['id'] ?>">View</a><a class="btn btn-danger btn-sm" href="index.php?page=admin&amp;section=stock-restock&amp;stock_item_id=<?= (int)$row['id'] ?>">Restock</a></div></td></tr><?php endforeach; endif; ?></tbody></table></div></div>
